class Solution {

public:

    int maxScore(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        s = vector<int>(nums.size() + 1);
        for (int k = 1; k <= nums.size(); k++) {
            s[k] = s[k - 1] + nums[k - 1];
        }
        ans = -1;
        for (int k = 3; k <= nums.size(); k++) {
            if (s[k - 1] > nums[k - 1]) {
                ans = max(ans, s[k]);
            }
        }
        return ans;
    }
private:
    vector<int> s;
};
